from functools import cmp_to_key

def semver_sort(versions):
    def parse(v):
        if '+' in v:
            v = v.split('+', 1)[0]
        if '-' in v:
            main, pre = v.split('-', 1)
        else:
            main, pre = v, None
        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        pre_ids = pre.split('.') if pre is not None else None
        return major, minor, patch, pre_ids

    def compare_pre(a, b):
        for x, y in zip(a, b):
            xd = x.isdigit()
            yd = y.isdigit()
            if xd and yd:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif xd and not yd:
                return -1
            elif not xd and yd:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def compare(v1, v2):
        m1, mn1, p1, pre1 = parse(v1)
        m2, mn2, p2, pre2 = parse(v2)
        if m1 != m2:
            return -1 if m1 < m2 else 1
        if mn1 != mn2:
            return -1 if mn1 < mn2 else 1
        if p1 != p2:
            return -1 if p1 < p2 else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        return compare_pre(pre1, pre2)

    return sorted(versions, key=cmp_to_key(compare))

